        }

        // Sort: oldest first by default (for triage), newest if requested
        items.sort((a, b) => {
          const dateA = new Date(a.created_at).getTime();
          const dateB = new Date(b.created_at).getTime();
          return options.newest ? dateB - dateA : dateA - dateB;
        });

