/**
 * Session event storage types and schemas.
 *
 * Provides JSONL-based event storage for agent sessions with:
 * - Session metadata tracking
 * - Append-only event logs
 * - Integration with kspec commit boundaries
 */

import { z } from "zod";

// ─── Session Status ──────────────────────────────────────────────────────────

/**
 * Session status enum.
 * - active: Session is in progress
 * - completed: Session ended normally
 * - abandoned: Session ended without explicit close
 */
export const SessionStatusSchema = z.enum(["active", "completed", "abandoned"]);
export type SessionStatus = z.infer<typeof SessionStatusSchema>;

// ─── Session Metadata ────────────────────────────────────────────────────────

/**
 * Session metadata stored in session.yaml.
 * AC-5: includes task_id (optional), agent_type, status, started_at, ended_at
 */
export const SessionMetadataSchema = z.object({
  /** Session ULID */
  id: z.string(),

  /** Optional task being worked on */
  task_id: z.string().optional(),

  /** Type of agent running the session */
  agent_type: z.string(),

  /** Current session status */
  status: SessionStatusSchema,

  /** When session started (ISO 8601) */
  started_at: z.string().datetime(),

  /** When session ended (ISO 8601) - only set when status != 'active' */
  ended_at: z.string().datetime().optional(),

  /** Whether end-loop has been requested for this session */
  end_requested: z.boolean().optional(),

  /** Reason for end-loop request */
  end_reason: z.string().optional(),

  /** Reason for session close (normal exit, signal, error) */
  close_reason: z.string().optional(),
});

export type SessionMetadata = z.infer<typeof SessionMetadataSchema>;

/**
 * Input for creating a new session.
 */
export const SessionMetadataInputSchema = SessionMetadataSchema.omit({
  status: true,
  started_at: true,
  ended_at: true,
}).extend({
  status: SessionStatusSchema.optional(),
  started_at: z.string().datetime().optional(),
});

export type SessionMetadataInput = z.infer<typeof SessionMetadataInputSchema>;

// ─── Event Types ─────────────────────────────────────────────────────────────

/**
 * Supported event types for session tracking.
 */
export const EventTypeSchema = z.enum([
  "session.start",
  "session.update",
  "session.end",
  "session.wrapup",
  "prompt.sent",
  "tool.call",
  "tool.result",
  "note",
]);

export type EventType = z.infer<typeof EventTypeSchema>;

// ─── Session Event ───────────────────────────────────────────────────────────

/**
 * A single event in the session log.
 * AC-2: Events include ts and seq auto-assigned on append.
 */
export const SessionEventSchema = z.object({
  /** Unix timestamp in milliseconds (auto-assigned) */
  ts: z.number(),

  /** Sequence number in session (auto-assigned, 0-indexed) */
  seq: z.number().int().nonnegative(),

  /** Event type */
  type: EventTypeSchema,

  /** Session this event belongs to */
  session_id: z.string(),

  /** Optional trace ID for correlation */
  trace_id: z.string().optional(),

  /** Type-specific event payload */
  data: z.unknown(),
});

export type SessionEvent = z.infer<typeof SessionEventSchema>;

/**
 * Input for appending an event (without auto-assigned fields).
 */
export const SessionEventInputSchema = SessionEventSchema.omit({
  ts: true,
  seq: true,
}).extend({
  ts: z.number().optional(),
  seq: z.number().int().nonnegative().optional(),
});

export type SessionEventInput = z.infer<typeof SessionEventInputSchema>;

// ─── Task Budget ────────────────────────────────────────────────────────────

/**
 * Task budget state stored in .kspec/sessions/{id}/budget.json.
 *
 * Budget lives on LOCAL filesystem (not shadow branch) to avoid contention
 * between ralph and spawned agents. Single-writer guarantee: ralph resets
 * only between iterations (agent not running), agent is only writer during
 * its turn.
 *
 * AC: @session-creation-and-env-injection ac-budget
 * AC: @session-creation-and-env-injection ac-budget-local
 * AC: @task-budget-enforcement ac-atomic-write
 */
export const TaskBudgetSchema = z.object({
  /** Maximum tasks that can be started per cycle/iteration */
  max_per_cycle: z.number().int().positive(),

  /** Number of tasks started in current cycle */
  started_this_cycle: z.number().int().nonnegative(),
});

export type TaskBudget = z.infer<typeof TaskBudgetSchema>;

/**
 * Session create command and library function tests.
 *
 * Tests for session creation, budget setup, environment injection,
 * and invalid session validation.
 *
 * Task: @implement-session-create-command
 * Spec: @session-creation-and-env-injection
 */

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import * as fs from "node:fs/promises";
import * as path from "node:path";
import * as os from "node:os";
import {
  createSessionWithBudget,
  validateSessionId,
  injectClaudeCodeEnv,
  injectCodexEnv,
  getFallbackInjectionInstructions,
  getSession,
  getBudget,
  getSessionBudgetPath,
  createSession,
} from "../src/sessions/store.js";
import type { SessionMetadataInput } from "../src/sessions/types.js";
import {
  kspec,
  kspecJson,
  setupTempFixtures,
  cleanupTempDir,
  createTempDir,
  testUlid,
} from "./helpers/cli.js";

// ─── Library Function: createSessionWithBudget ──────────────────────────────

describe("createSessionWithBudget", () => {
  let testDir: string;

  beforeEach(async () => {
    testDir = await createTempDir("kspec-session-create-");
    // Create sessions directory
    await fs.mkdir(path.join(testDir, "sessions"), { recursive: true });
  });

  afterEach(async () => {
    await cleanupTempDir(testDir);
  });

  // AC: @session-creation-and-env-injection ac-create
  it("should create a session with status active and return metadata", async () => {
    const sessionId = testUlid("SESS", 1);
    const result = await createSessionWithBudget(testDir, {
      id: sessionId,
      agent_type: "claude-code",
    });

    expect(result.session_id).toBe(sessionId);
    expect(result.session.id).toBe(sessionId);
    expect(result.session.status).toBe("active");
    expect(result.session.agent_type).toBe("claude-code");
    expect(result.session.started_at).toBeTruthy();
    expect(result.budget).toBeNull();
  });

  // AC: @session-creation-and-env-injection ac-create
  it("should create session directory with session.yaml", async () => {
    const sessionId = testUlid("SESS", 2);
    await createSessionWithBudget(testDir, {
      id: sessionId,
      agent_type: "codex-cli",
    });

    const sessionDir = path.join(testDir, "sessions", sessionId);
    const stat = await fs.stat(sessionDir);
    expect(stat.isDirectory()).toBe(true);

    const metadataPath = path.join(sessionDir, "session.yaml");
    const content = await fs.readFile(metadataPath, "utf-8");
    expect(content).toContain("status: active");
    expect(content).toContain("agent_type: codex-cli");
  });

  // AC: @session-creation-and-env-injection ac-budget
  it("should create budget.json when budget option provided", async () => {
    const sessionId = testUlid("SESS", 3);
    const result = await createSessionWithBudget(testDir, {
      id: sessionId,
      agent_type: "claude-code",
      budget: 5,
    });

    expect(result.budget).not.toBeNull();
    expect(result.budget!.max_per_cycle).toBe(5);
    expect(result.budget!.started_this_cycle).toBe(0);
  });

  // AC: @session-creation-and-env-injection ac-budget-local
  it("should store budget.json on local filesystem in session directory", async () => {
    const sessionId = testUlid("SESS", 4);
    await createSessionWithBudget(testDir, {
      id: sessionId,
      agent_type: "claude-code",
      budget: 3,
    });

    const budgetPath = getSessionBudgetPath(testDir, sessionId);
    const content = await fs.readFile(budgetPath, "utf-8");
    const budget = JSON.parse(content);
    expect(budget.max_per_cycle).toBe(3);
    expect(budget.started_this_cycle).toBe(0);
    // Verify it's in the expected location
    expect(budgetPath).toContain(path.join("sessions", sessionId, "budget.json"));
  });

  // AC: @session-creation-and-env-injection ac-library
  it("should return metadata without console output", async () => {
    const sessionId = testUlid("SESS", 5);
    // Capture console output
    const consoleLogs: string[] = [];
    const originalLog = console.log;
    console.log = (...args: unknown[]) => consoleLogs.push(args.join(" "));

    try {
      const result = await createSessionWithBudget(testDir, {
        id: sessionId,
        agent_type: "claude-code",
        budget: 2,
      });

      // Library function should not produce console output
      expect(consoleLogs).toHaveLength(0);

      // Should return complete metadata
      expect(result.session_id).toBe(sessionId);
      expect(result.session.id).toBe(sessionId);
      expect(result.session.status).toBe("active");
      expect(result.budget).not.toBeNull();
      expect(result.budget!.max_per_cycle).toBe(2);
    } finally {
      console.log = originalLog;
    }
  });

  it("should include task_id when provided", async () => {
