   997→    }
   998→  }
   999→
  1000→  return {
  1001→    agent: {
  1002→      detected: detected.type,
  1003→      confidence: detected.confidence,
  1004→    },
  1005→    hooks,
  1006→    skills,
  1007→    plugin,
  1008→    agentsMd,
  1009→    seeding,
  1010→  };
