describe("session create CLI", () => {
  let testDir: string;

  beforeEach(async () => {
    testDir = await setupTempFixtures();
  });

  afterEach(async () => {
    await cleanupTempDir(testDir);
  });

  // AC: @session-creation-and-env-injection ac-create
