 * @returns Session metadata and optional budget (no console output)
 */
export async function createSessionWithBudget(
  specDir: string,
  input: {
    id: string;
    agent_type: string;
    task_id?: string;
    budget?: number;
  },
): Promise<{
  session_id: string;
