  1326→type SortField =
  1327→  | "started_at"
  1328→  | "duration"
  1329→  | "events"
  1330→  | "iterations"
  1331→  | "tasks_completed";
  1332→
  1333→const VALID_SORT_FIELDS: SortField[] = [
