   370→const REF_FIELDS = [
   371→  "depends_on",
   372→  "blocked_by",
   373→  "implements",
   374→  "relates_to",
   375→  "tests",
   376→  "supersedes",
   377→  "spec_ref",
   378→  "plan_ref", // AC: @plan-validation ac-10 - Plan reference
